model_config.built_in_css:
ai{
  display:block;
  position:relative;
  font-family:"Klee One","Comic Sans MS","Xingkai SC","STXingkai",'PingFang SC',"Microsoft YaHei",sans-serif;
  font-size:15px;
  line-height:1.75;
  color:#3b3630;
  background-color:#fdfcf7;
  background-image:
    linear-gradient(rgba(120,160,200,.13) 1px,transparent 1px),
    linear-gradient(90deg,rgba(120,160,200,.13) 1px,transparent 1px),
    radial-gradient(circle at 20% 10%,rgba(255,214,140,.18),transparent 45%),
    radial-gradient(circle at 85% 90%,rgba(160,210,230,.18),transparent 45%);
  background-size:22px 22px,22px 22px,100% 100%,100% 100%;
  padding:16px 13px 22px;
  border-radius:6px 10px 7px 12px;
  box-shadow:
    3px 4px 0 rgba(60,50,40,.10),
    6px 8px 0 rgba(60,50,40,.05);
  overflow:hidden;
}
ai::before{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  background-image:
    repeating-linear-gradient(0deg,transparent 0 21px,rgba(180,150,120,.05) 21px 22px);
  opacity:.6;
}

/* ── 顶部卡片框 ─────────────────── */
hd{
  display:flex;
  flex-wrap:wrap;
  gap:9px;
  align-items:stretch;
  margin-bottom:16px;
}
hd::after{
  content:"";
  flex-basis:100%;
  height:0;
  border-bottom:2.5px dashed rgba(90,130,170,.35);
  margin-top:2px;
}

/* 时间 / 地点卡 */
t{
  flex:0 0 auto;
  display:inline-flex;
  align-items:center;
  padding:7px 13px;
  font-size:13px;
  font-weight:700;
  letter-spacing:.4px;
  color:#2f4a63;
  background:#fff9e6;
  border:2.5px solid #5a82aa;
  border-radius:14px 4px 12px 5px;
  box-shadow:2px 3px 0 rgba(90,130,170,.35);
  transform:rotate(-1.4deg);
  position:relative;
}
t::before{
  content:"";
  position:absolute;
  inset:2px;
  border:1px solid rgba(90,130,170,.25);
  border-radius:11px 3px 9px 4px;
  pointer-events:none;
}

/* NPC便签卡 */
c{
  flex:1 1 150px;
  min-width:140px;
  display:flex;
  flex-direction:column;
  gap:2px;
  padding:8px 11px 9px 14px;
  background:#fffaf0;
  border:2.5px solid #d98a9a;
  border-radius:5px 14px 4px 12px;
  box-shadow:3px 4px 0 rgba(217,138,154,.28);
  transform:rotate(1.1deg);
  position:relative;
  transition:transform .18s ease,box-shadow .18s ease;
}
c:nth-of-type(even){transform:rotate(-1.3deg);box-shadow:3px 4px 0 rgba(150,180,120,.28);border-color:#9cb87a;}
c::before{
  content:"";
  position:absolute;
  left:-2px;
  top:8px;
  bottom:8px;
  width:4px;
  background:repeating-linear-gradient(180deg,#d98a9a 0 5px,transparent 5px 9px);
  border-radius:2px;
}
c:nth-of-type(even)::before{background:repeating-linear-gradient(180deg,#9cb87a 0 5px,transparent 5px 9px);}
c:hover{transform:rotate(0deg) translateY(-2px);box-shadow:4px 6px 0 rgba(217,138,154,.35);}
cn{
  font-size:15px;
  font-weight:800;
  color:#b8566c;
  letter-spacing:.5px;
}
c:nth-of-type(even) cn{color:#5e8038;}
ci,cr,cp{
  font-size:12px;
  line-height:1.5;
  color:#6b6258;
}
cr{color:#3b3630;font-weight:600;}
cp{
  font-style:italic;
  color:#a06a7a;
  border-top:1px dashed rgba(160,106,122,.35);
  padding-top:2px;
  margin-top:1px;
}

/* ── 正文 ─────────────────────── */
tx{display:block;margin-bottom:18px;}
tx p{
  margin:0 0 .65em;
  text-indent:1.6em;
  letter-spacing:.2px;
}
tx p:last-child{margin-bottom:0;}
u{
  font-style:normal;
  font-weight:700;
  color:#2f6ea8;
  text-decoration:none;
  background:linear-gradient(transparent 62%,rgba(120,180,235,.4) 62%);
  padding:0 1px;
}
v{
  font-style:normal;
  font-weight:700;
  color:#c2456a;
  text-decoration:none;
  background:linear-gradient(transparent 62%,rgba(240,160,190,.45) 62%);
  padding:0 1px;
}

/* ── 状态栏容器 ─────────────────── */
st{display:block;}

/* 心声 */
x{
  display:block;
  position:relative;
  margin-bottom:14px;
  padding:11px 14px 11px 34px;
  font-size:13.5px;
  font-style:italic;
  color:#6a4a70;
  background:#f3eefb;
  border:2px solid #b79ad4;
  border-radius:12px 5px 13px 6px;
  box-shadow:2.5px 3px 0 rgba(183,154,212,.3);
  transform:rotate(-.7deg);
}
x::before{
  content:"“";
  position:absolute;
  left:10px;
  top:4px;
  font-size:30px;
  font-style:normal;
  color:#b79ad4;
  line-height:1;
  font-family:Georgia,serif;
}

/* 折叠区块 */
details{
  margin-bottom:12px;
  background:#fffdf6;
  border:2.5px solid #8a9bb0;
  border-radius:5px 13px 6px 12px;
  box-shadow:3px 4px 0 rgba(138,155,176,.22);
  overflow:hidden;
}
details:nth-of-type(2){transform:rotate(.5deg);border-color:#c99a5e;box-shadow:3px 4px 0 rgba(201,154,94,.22);}
details:nth-of-type(3){transform:rotate(-.5deg);border-color:#9cb87a;box-shadow:3px 4px 0 rgba(156,184,122,.22);}
summary{
  padding:9px 14px;
  font-size:14.5px;
  font-weight:800;
  letter-spacing:.6px;
  cursor:pointer;
  list-style:none;
  color:#3f5568;
  background:#f4f8fb;
  border-bottom:2px dashed rgba(138,155,176,.4);
  display:flex;
  align-items:center;
  justify-content:space-between;
  transition:background .18s ease;
}
summary::-webkit-details-marker{display:none;}
summary::after{
  content:"▾";
  font-size:13px;
  color:#8a9bb0;
  transition:transform .22s ease;
}
details[open]>summary::after{transform:rotate(180deg);}
summary:hover{background:#e9f2f9;}
details:nth-of-type(2)>summary{color:#8a6528;background:#fbf5ea;border-bottom-color:rgba(201,154,94,.4);}
details:nth-of-type(2)>summary::after{color:#c99a5e;}
details:nth-of-type(3)>summary{color:#4f7030;background:#f4faee;border-bottom-color:rgba(156,184,122,.4);}
details:nth-of-type(3)>summary::after{color:#9cb87a;}

/* 区块内段落 */
details p{
  margin:0;
  padding:9px 14px 11px;
  font-size:13px;
  line-height:1.7;
}
details p + p{
  border-top:2px dashed rgba(160,150,140,.28);
}

/* 字段：名 + 值 */
f{
  display:inline-block;
  min-width:62px;
  margin-right:8px;
  padding:1px 8px 2px;
  font-size:12.5px;
  font-weight:800;
  color:#fff;
  background:#8a9bb0;
  border-radius:8px 3px 8px 3px;
  box-shadow:1.5px 2px 0 rgba(0,0,0,.13);
  transform:rotate(-.8deg);
  vertical-align:1px;
}
d{
  display:block;
  text-indent:0;
  color:#443e37;
}
d f{
  background:#c99a5e;
}
details:nth-of-type(3) d f{background:#9cb87a;}

/* NPC 小标题分块 */
p[t]::before{
  content:"📌";
  font-size:12px;
  margin-right:5px;
  opacity:.85;
}
p[t="玩家"]::before{content:"🎴";}
p[t="短期记忆"]::before{content:"📝";}
p[t="长期记忆"]::before{content:"📚";}
p[t="历史总记忆"]::before{content:"🕰️";}
p[t="行动"]::before{content:"✏️";}

/* NPC名加粗字段 */
p[s] f{
  background:#d98a9a;
}

/* ── 行动选项 2×2 ───────────────── */
p[t="行动"]{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:9px;
  padding:12px 14px 14px;
}
p[t="行动"]::before{
  content:"✏️";
  grid-column:1 / -1;
  font-size:12px;
  opacity:.85;
}
o{
  display:block;
  padding:9px 11px;
  font-size:13px;
  font-weight:700;
  line-height:1.5;
  color:#3b3630;
  background:#fffdf6;
  border:2.5px solid #b0b8c0;
  border-radius:5px 12px 6px 11px;
  box-shadow:2.5px 3px 0 rgba(120,120,120,.22);
  cursor:pointer;
  transition:transform .16s ease,box-shadow .16s ease,background .16s ease;
}
o:nth-child(2){transform:rotate(-1deg);border-color:#7eb0d8;box-shadow:2.5px 3px 0 rgba(126,176,216,.3);}
o:nth-child(3){transform:rotate(1deg);border-color:#8fc47a;box-shadow:2.5px 3px 0 rgba(143,196,122,.3);}
o:nth-child(4){transform:rotate(-.8deg);border-color:#cf7a98;box-shadow:2.5px 3px 0 rgba(207,122,152,.3);}
o:nth-child(5){transform:rotate(.6deg);border-color:#b79ad4;box-shadow:2.5px 3px 0 rgba(183,154,212,.3);}
o:hover{
  transform:rotate(0deg) translateY(-2px);
  background:#fff9e6;
  box-shadow:3px 5px 0 rgba(120,120,120,.3);
}

/* 手绘标题感 */
hd::after{
  font-family:inherit;
}

/* 滚动条（移动端隐藏感） */
ai ::-webkit-scrollbar{width:6px;}
ai ::-webkit-scrollbar-thumb{background:rgba(138,155,176,.5);border-radius:3px;}
